INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("雨宮天", 1, "プリン大好きゴースト娘", "B", 32, 0, 14, 100701, "プリンを食べること", "魔族", "ミヤコ", "悪魔偽王国軍（ディアボロス）", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 7, 130, 23);
