INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("植田佳奈", 6, "泣き虫で臆病な守ってあげたい女の子", "B", 40, 0, 12, 108501, "観劇、おままごと", "ヒューマン", "クルミ（クリスマス）", "サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 9, 150, 9);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("芹澤優", 5, "ぷうきちといつも一緒！", "B", 38, 0, 14, 108601, "屋内でできる遊び", "ヒューマン", "アヤネ（クリスマス）", "サレンディア救護院", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 9, 148, 10);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("東山奈央", 8, "人助けが大好き！　前向き格闘娘", "A", 44, 0, 16, 108701, "人助け、応援", "獣人族", "ヒヨリ（ニューイヤー）", "トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 2, 155, 27);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("種田梨沙", 4, "戦闘のサポートが得意な、心優しい少女", "O", 47, 0, 17, 108801, "料理、人間観察", "ヒューマン", "ユイ（ニューイヤー）", "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 2, 158, 5);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("早見沙織", 1, "クールで何事にも真っ直ぐな剣士", "B", 46, 0, 18, 108901, "読書、乗馬、お茶", "魔族", "レイ（ニューイヤー）", "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 2, 163, 12);
